export default [{"w":"acquit","pos":"verb","def":"To declare in court that someone is not guilty of a crime.","defId":"Membebaskan; menyatakan di pengadilan bahwa seseorang tidak bersalah.","ex":"The jury acquitted her of all charges due to lack of evidence.","exId":"Juri membebaskannya dari semua dakwaan karena kurangnya bukti.","colloc":["acquit of charges","be acquitted","acquit the defendant"],"theme":"law"},{"w":"adjourn","pos":"verb","def":"to stop a meeting or trial for a period of time","defId":"menunda atau menskors sidang atau rapat untuk sementara","ex":"The judge decided to adjourn the trial until the following morning.","exId":"Hakim memutuskan untuk menunda persidangan hingga keesokan paginya.","colloc":["adjourn the trial","adjourn a hearing"],"theme":"law"},{"w":"adjudicate","pos":"verb","def":"to act as a judge and make an official decision about a dispute","defId":"mengadili; memutuskan suatu perselisihan secara resmi","ex":"An independent panel was appointed to adjudicate the dispute between the two firms.","exId":"Sebuah panel independen ditunjuk untuk mengadili perselisihan antara kedua perusahaan itu.","colloc":["adjudicate a dispute","adjudicate on"],"theme":"law"},{"w":"affidavit","pos":"noun","def":"A written statement that you swear is true, used as evidence in court.","defId":"Pernyataan tertulis yang disumpah kebenarannya, digunakan sebagai bukti di pengadilan.","ex":"She signed an affidavit confirming that she had witnessed the accident.","exId":"Dia menandatangani surat pernyataan bersumpah yang menegaskan bahwa dia menyaksikan kecelakaan itu.","colloc":["sign an affidavit","sworn affidavit","file an affidavit"],"theme":"law"},{"w":"alibi","pos":"noun","def":"Evidence that a person was somewhere else when an offence took place.","defId":"Bukti bahwa seseorang berada di tempat lain saat suatu tindak pidana terjadi.","ex":"He had a solid alibi and was quickly cleared by the court.","exId":"Dia memiliki alibi yang kuat dan cepat dibebaskan oleh pengadilan.","colloc":["solid alibi","provide an alibi","watertight alibi"],"theme":"law"},{"w":"amend","pos":"verb","def":"To make small changes to a law, document, or agreement in order to improve it.","defId":"Mengamandemen; membuat perubahan pada hukum, dokumen, atau perjanjian untuk memperbaikinya.","ex":"Parliament voted to amend the law on data privacy.","exId":"Parlemen memberikan suara untuk mengamandemen undang-undang tentang privasi data.","colloc":["amend a law","amend the constitution","amend a contract"],"theme":"law"},{"w":"amnesty","pos":"noun","def":"an official decision to pardon people or forgive past offences","defId":"amnesti; pengampunan resmi atas pelanggaran di masa lalu","ex":"The government offered an amnesty to anyone who surrendered illegal weapons.","exId":"Pemerintah menawarkan amnesti kepada siapa pun yang menyerahkan senjata ilegal.","colloc":["grant an amnesty","general amnesty"],"theme":"law"},{"w":"annul","pos":"verb","def":"to declare officially that something such as a marriage or law no longer exists","defId":"membatalkan; menyatakan tidak berlaku secara resmi","ex":"The court agreed to annul the marriage on the grounds of fraud.","exId":"Pengadilan setuju untuk membatalkan pernikahan itu atas dasar penipuan.","colloc":["annul a marriage","annul a contract"],"theme":"law"},{"w":"arbitration","pos":"noun","def":"The settling of a dispute by an independent person rather than in court.","defId":"Arbitrase; penyelesaian sengketa oleh pihak ketiga yang netral, bukan melalui pengadilan.","ex":"Both sides agreed to settle the dispute through arbitration.","exId":"Kedua pihak sepakat menyelesaikan sengketa melalui arbitrase.","colloc":["binding arbitration","go to arbitration","arbitration process"],"theme":"law"},{"w":"arraign","pos":"verb","def":"to bring someone to court to formally hear the charges against them","defId":"menghadapkan tersangka ke pengadilan untuk mendengarkan dakwaan","ex":"The suspect was arraigned on charges of fraud the next morning.","exId":"Tersangka dihadapkan ke pengadilan atas dakwaan penipuan keesokan paginya.","colloc":["arraign on charges","arraign before a court"],"theme":"law"},{"w":"barrister","pos":"noun","def":"A lawyer qualified to argue cases in the higher courts, especially in the UK.","defId":"Pengacara yang berwenang beracara di pengadilan tinggi, terutama di Inggris.","ex":"The defendant hired a leading barrister to represent him at trial.","exId":"Terdakwa menyewa seorang barrister terkemuka untuk mewakilinya di persidangan.","colloc":["defence barrister","leading barrister","instruct a barrister"],"theme":"law"},{"w":"binding","pos":"adjective","def":"That must be obeyed because it is a legal obligation.","defId":"Mengikat; wajib dipatuhi karena merupakan kewajiban hukum.","ex":"Once signed, the agreement is legally binding on both parties.","exId":"Setelah ditandatangani, perjanjian itu mengikat secara hukum bagi kedua pihak.","colloc":["legally binding","binding agreement","binding contract"],"theme":"law"},{"w":"breach","pos":"noun","def":"An act of breaking a law, rule, or agreement.","defId":"Pelanggaran terhadap hukum, aturan, atau perjanjian.","ex":"Sharing the confidential files was a clear breach of contract.","exId":"Membagikan berkas rahasia itu jelas merupakan pelanggaran kontrak.","colloc":["breach of contract","breach of duty","material breach"],"theme":"law"},{"w":"bylaw","pos":"noun","def":"a rule made by a local authority or organisation to control its own affairs","defId":"peraturan lokal atau internal suatu organisasi","ex":"Parking on the green is prohibited under a council bylaw.","exId":"Parkir di lapangan hijau dilarang menurut peraturan lokal dewan kota.","colloc":["council bylaw","breach a bylaw"],"theme":"law"},{"w":"charter","pos":"noun","def":"a formal document stating the rights, aims, or principles of a group","defId":"piagam; dokumen resmi yang menyatakan hak atau asas suatu kelompok","ex":"The organisation's charter guarantees every member the right to vote.","exId":"Piagam organisasi itu menjamin hak setiap anggota untuk memberikan suara.","colloc":["a charter of rights","under the charter"],"theme":"law"},{"w":"claimant","pos":"noun","def":"a person who makes a legal claim, especially in a civil case","defId":"penggugat; pihak yang mengajukan tuntutan hukum","ex":"The claimant is seeking damages for breach of contract.","exId":"Penggugat menuntut ganti rugi atas pelanggaran kontrak.","colloc":["the claimant alleges","successful claimant"],"theme":"law"},{"w":"clause","pos":"noun","def":"A distinct section or provision in a legal document or contract.","defId":"Klausul; bagian atau ketentuan tertentu dalam dokumen hukum atau kontrak.","ex":"The contract contains a clause allowing either party to cancel with notice.","exId":"Kontrak itu memuat klausul yang memungkinkan kedua pihak membatalkannya dengan pemberitahuan.","colloc":["contract clause","confidentiality clause","under the clause"],"theme":"law"},{"w":"clemency","pos":"noun","def":"kindness shown by reducing a punishment; mercy from those in power","defId":"keringanan hukuman; belas kasihan dari pihak yang berwenang","ex":"The defence lawyers appealed to the court for clemency.","exId":"Para pengacara pembela memohon keringanan hukuman kepada pengadilan.","colloc":["appeal for clemency","grant clemency"],"theme":"law"},{"w":"codify","pos":"verb","def":"to arrange laws or rules into a clear, organised system","defId":"mengkodifikasi; menyusun hukum menjadi satu sistem tertulis yang teratur","ex":"The new act aims to codify decades of scattered employment law.","exId":"Undang-undang baru itu bertujuan mengkodifikasi hukum ketenagakerjaan yang tersebar selama puluhan tahun.","colloc":["codify the law","codify rules"],"theme":"law"},{"w":"compliance","pos":"noun","def":"The act of obeying a law, rule, or official requirement.","defId":"Kepatuhan; tindakan menaati hukum, aturan, atau ketentuan resmi.","ex":"All firms must ensure compliance with the new data protection regulations.","exId":"Semua perusahaan harus memastikan kepatuhan terhadap peraturan perlindungan data yang baru.","colloc":["ensure compliance","regulatory compliance","in compliance with"],"theme":"law"},{"w":"consensual","pos":"adjective","def":"agreed to by everyone involved; based on mutual consent","defId":"berdasarkan persetujuan bersama; disepakati oleh semua pihak","ex":"The contract is only valid if it results from a consensual agreement between both parties.","exId":"Kontrak itu hanya sah jika berasal dari kesepakatan atas dasar persetujuan kedua belah pihak.","colloc":["consensual agreement","fully consensual"],"theme":"law"},{"w":"constitution","pos":"noun","def":"The system of fundamental laws and principles by which a country is governed.","defId":"Undang-undang dasar; kumpulan hukum dan prinsip mendasar yang mengatur suatu negara.","ex":"The right to free speech is protected by the country's constitution.","exId":"Hak atas kebebasan berbicara dilindungi oleh konstitusi negara itu.","colloc":["written constitution","amend the constitution","under the constitution"],"theme":"law"},{"w":"contractual","pos":"adjective","def":"Relating to or stated in a legally binding contract.","defId":"Berkaitan dengan atau tercantum dalam kontrak yang mengikat secara hukum; kontraktual.","ex":"The supplier failed to meet its contractual obligations.","exId":"Pemasok gagal memenuhi kewajiban kontraktualnya.","colloc":["contractual obligation","contractual terms","contractual agreement"],"theme":"law"},{"w":"counsel","pos":"noun","def":"a lawyer or group of lawyers who represent someone in court","defId":"penasihat hukum; pengacara yang mewakili seseorang di pengadilan","ex":"The defence counsel argued that the evidence had been obtained unlawfully.","exId":"Penasihat hukum pembela berpendapat bahwa bukti itu diperoleh secara tidak sah.","colloc":["defence counsel","legal counsel"],"theme":"law"},{"w":"culpable","pos":"adjective","def":"deserving blame for having done something wrong","defId":"bersalah; layak dipersalahkan atas kesalahan","ex":"The inquiry found the manager culpable for ignoring the safety warnings.","exId":"Penyelidikan menemukan bahwa manajer itu bersalah karena mengabaikan peringatan keselamatan.","colloc":["culpable of","held culpable"],"theme":"law"},{"w":"custodial","pos":"adjective","def":"relating to being kept in prison, or to having legal care of someone","defId":"berkaitan dengan penahanan di penjara atau dengan hak asuh","ex":"The judge handed down a custodial sentence of five years.","exId":"Hakim menjatuhkan hukuman penjara selama lima tahun.","colloc":["custodial sentence","custodial care"],"theme":"law"},{"w":"damages","pos":"noun","def":"Money that a court orders someone to pay as compensation for loss or injury.","defId":"Ganti rugi; uang yang diperintahkan pengadilan untuk dibayar sebagai kompensasi atas kerugian atau cedera.","ex":"The court awarded her fifty thousand pounds in damages for the injury.","exId":"Pengadilan memberinya ganti rugi sebesar lima puluh ribu pound atas cedera itu.","colloc":["award damages","claim damages","pay damages"],"theme":"law"},{"w":"deposition","pos":"noun","def":"a formal, written statement made under oath for use in court","defId":"kesaksian tertulis di bawah sumpah untuk digunakan di pengadilan","ex":"The lawyer read out the witness's deposition during the trial.","exId":"Pengacara membacakan kesaksian tertulis saksi itu selama persidangan.","colloc":["give a deposition","sworn deposition"],"theme":"law"},{"w":"enforce","pos":"verb","def":"To make sure that a law or rule is obeyed.","defId":"Menegakkan; memastikan suatu hukum atau aturan dipatuhi.","ex":"The police are there to enforce the law, not to make it.","exId":"Polisi ada untuk menegakkan hukum, bukan membuatnya.","colloc":["enforce the law","strictly enforce","enforce a rule"],"theme":"law"},{"w":"enforceable","pos":"adjective","def":"able to be made effective or obeyed by law","defId":"dapat ditegakkan atau dipaksakan menurut hukum","ex":"A purely verbal promise is rarely enforceable in a court of law.","exId":"Janji yang hanya bersifat lisan jarang dapat ditegakkan di pengadilan.","colloc":["legally enforceable","enforceable contract"],"theme":"law"},{"w":"entitled","pos":"adjective","def":"having the legal right to have or do something","defId":"berhak; memiliki hak atas sesuatu","ex":"Every worker is entitled to a minimum period of paid leave each year.","exId":"Setiap pekerja berhak atas masa cuti berbayar minimum setiap tahun.","colloc":["entitled to","legally entitled"],"theme":"law"},{"w":"entitlement","pos":"noun","def":"The right to have or receive something under the law or rules.","defId":"Hak; kewenangan untuk memiliki atau menerima sesuatu berdasarkan hukum atau aturan.","ex":"All employees have a statutory entitlement to paid holiday.","exId":"Semua karyawan memiliki hak cuti berbayar sesuai undang-undang.","colloc":["legal entitlement","statutory entitlement","holiday entitlement"],"theme":"law"},{"w":"exempt","pos":"adjective","def":"free from a duty, rule, or payment that applies to others","defId":"dikecualikan; bebas dari suatu kewajiban atau aturan","ex":"Diplomats are exempt from prosecution under the laws of the host country.","exId":"Para diplomat dikecualikan dari penuntutan menurut hukum negara tuan rumah.","colloc":["exempt from","tax-exempt"],"theme":"law"},{"w":"extradition","pos":"noun","def":"the official sending of an accused person back to another country to stand trial","defId":"ekstradisi; penyerahan tersangka ke negara lain untuk diadili","ex":"The suspect is fighting extradition to the country where the crime took place.","exId":"Tersangka melawan ekstradisi ke negara tempat kejahatan itu terjadi.","colloc":["extradition treaty","fight extradition"],"theme":"law"},{"w":"grievance","pos":"noun","def":"A formal complaint about being treated unfairly, especially at work.","defId":"Keluhan resmi tentang perlakuan tidak adil, terutama di tempat kerja.","ex":"He filed a grievance against his manager for discrimination.","exId":"Dia mengajukan keluhan resmi terhadap manajernya atas diskriminasi.","colloc":["file a grievance","grievance procedure","legitimate grievance"],"theme":"law"},{"w":"illicit","pos":"adjective","def":"not allowed by law or by social rules; illegal","defId":"terlarang; gelap dan tidak sah menurut hukum","ex":"The police seized a large quantity of illicit drugs during the raid.","exId":"Polisi menyita sejumlah besar narkoba ilegal saat penggerebekan.","colloc":["illicit trade","illicit drugs"],"theme":"law"},{"w":"indemnify","pos":"verb","def":"to promise to pay someone for any loss or damage they suffer","defId":"mengganti rugi; menjamin ganti rugi atas kerugian","ex":"The clause requires the company to indemnify its clients against any legal costs.","exId":"Klausul itu mewajibkan perusahaan untuk mengganti rugi kliennya atas segala biaya hukum.","colloc":["indemnify against","indemnify a party"],"theme":"law"},{"w":"indict","pos":"verb","def":"To formally charge someone with a serious crime.","defId":"Mendakwa seseorang secara resmi atas kejahatan serius.","ex":"The grand jury voted to indict him on charges of fraud.","exId":"Dewan juri memutuskan untuk mendakwanya atas tuduhan penipuan.","colloc":["indict on charges","formally indict","indict someone"],"theme":"law"},{"w":"infringe","pos":"verb","def":"to break a law or rule, or to limit someone's rights","defId":"melanggar hukum atau aturan; menyalahi hak seseorang","ex":"The new surveillance powers could infringe citizens' right to privacy.","exId":"Kewenangan pengawasan yang baru dapat melanggar hak privasi warga.","colloc":["infringe a right","infringe copyright"],"theme":"law"},{"w":"injunction","pos":"noun","def":"A court order that forces someone to do, or stop doing, a particular act.","defId":"Perintah pengadilan yang mewajibkan seseorang melakukan atau menghentikan suatu tindakan.","ex":"The company obtained an injunction to stop the newspaper publishing the story.","exId":"Perusahaan itu memperoleh perintah larangan pengadilan untuk mencegah koran menerbitkan berita tersebut.","colloc":["obtain an injunction","court injunction","grant an injunction"],"theme":"law"},{"w":"judicial","pos":"adjective","def":"Relating to the courts, judges, or the administration of justice.","defId":"Berkaitan dengan pengadilan, hakim, atau penyelenggaraan peradilan; yudisial.","ex":"The judicial system is designed to be independent of the government.","exId":"Sistem peradilan dirancang agar independen dari pemerintah.","colloc":["judicial system","judicial review","judicial independence"],"theme":"law"},{"w":"jurisprudence","pos":"noun","def":"The study or theory of law and the principles on which it is based.","defId":"Ilmu atau filsafat hukum; teori tentang hukum dan asas-asasnya.","ex":"Her thesis explored recent developments in human rights jurisprudence.","exId":"Tesisnya mengeksplorasi perkembangan terbaru dalam yurisprudensi hak asasi manusia.","colloc":["legal jurisprudence","human rights jurisprudence","constitutional jurisprudence"],"theme":"law"},{"w":"jury","pos":"noun","def":"A group of citizens who listen to evidence in court and decide the verdict.","defId":"Juri; sekelompok warga yang mendengarkan bukti di pengadilan dan menentukan putusan.","ex":"The jury found the defendant not guilty on all charges.","exId":"Juri menyatakan terdakwa tidak bersalah atas semua dakwaan.","colloc":["jury trial","the jury decides","serve on a jury"],"theme":"law"},{"w":"lawful","pos":"adjective","def":"allowed or recognised by law; legal","defId":"sah menurut hukum; dibenarkan oleh undang-undang","ex":"Peaceful protest is a lawful way for citizens to express their dissent.","exId":"Protes damai adalah cara yang sah bagi warga untuk menyatakan ketidaksetujuan mereka.","colloc":["lawful activity","lawful owner"],"theme":"law"},{"w":"lawsuit","pos":"noun","def":"A claim or dispute brought before a court of law for a decision.","defId":"Gugatan hukum; perkara yang diajukan ke pengadilan untuk diputuskan.","ex":"The company faces a lawsuit over its handling of customer data.","exId":"Perusahaan itu menghadapi gugatan atas cara mereka menangani data pelanggan.","colloc":["file a lawsuit","face a lawsuit","settle a lawsuit"],"theme":"law"},{"w":"legality","pos":"noun","def":"the fact of being allowed by law; whether something is legal","defId":"keabsahan menurut hukum; legalitas suatu tindakan","ex":"Campaigners questioned the legality of detaining the protesters without charge.","exId":"Para aktivis mempertanyakan legalitas penahanan para demonstran tanpa dakwaan.","colloc":["question the legality","the legality of"],"theme":"law"},{"w":"legitimate","pos":"adjective","def":"Allowed by law, or fair and reasonable.","defId":"Sah menurut hukum; wajar dan dapat diterima.","ex":"The workers had a legitimate grievance about their unpaid wages.","exId":"Para pekerja memiliki keluhan yang sah tentang upah mereka yang belum dibayar.","colloc":["legitimate claim","perfectly legitimate","legitimate business"],"theme":"law"},{"w":"liable","pos":"adjective","def":"Legally responsible for something, such as paying a cost or damage.","defId":"Bertanggung jawab secara hukum atas sesuatu, seperti membayar biaya atau kerugian.","ex":"The landlord is liable for any structural repairs to the building.","exId":"Pemilik rumah bertanggung jawab secara hukum atas segala perbaikan struktur bangunan.","colloc":["held liable","liable for damages","legally liable"],"theme":"law"},{"w":"licit","pos":"adjective","def":"permitted by law; the opposite of illicit","defId":"diperbolehkan secara hukum; kebalikan dari terlarang","ex":"The report clearly distinguishes between the licit and illicit use of firearms.","exId":"Laporan itu dengan jelas membedakan antara penggunaan senjata api yang legal dan yang ilegal.","colloc":["licit trade","licit use"],"theme":"law"},{"w":"litigant","pos":"noun","def":"a person who is involved in a lawsuit","defId":"pihak yang berperkara dalam gugatan pengadilan","ex":"Both litigants were ordered to attend a mediation session before the hearing.","exId":"Kedua pihak yang berperkara diperintahkan menghadiri sesi mediasi sebelum sidang.","colloc":["a litigant in person","the losing litigant"],"theme":"law"},{"w":"litigation","pos":"noun","def":"The process of resolving a dispute by taking it through the courts.","defId":"Proses penyelesaian sengketa melalui pengadilan; perkara hukum.","ex":"The dispute dragged on for years of costly litigation.","exId":"Sengketa itu berlarut-larut selama bertahun-tahun dengan litigasi yang mahal.","colloc":["costly litigation","commercial litigation","involved in litigation"],"theme":"law"},{"w":"magistrate","pos":"noun","def":"An official who acts as a judge in a lower court dealing with minor cases.","defId":"Hakim yang menangani perkara-perkara ringan di pengadilan tingkat bawah.","ex":"The magistrate fined him two hundred pounds for the traffic offence.","exId":"Hakim itu mendendanya dua ratus pound atas pelanggaran lalu lintas.","colloc":["local magistrate","magistrates' court","appear before a magistrate"],"theme":"law"},{"w":"mandatory","pos":"adjective","def":"required by law or by a rule; compulsory","defId":"wajib; diharuskan oleh hukum atau aturan","ex":"The law imposes a mandatory sentence on anyone convicted of the offence.","exId":"Undang-undang itu menjatuhkan hukuman wajib bagi siapa pun yang terbukti bersalah atas pelanggaran tersebut.","colloc":["mandatory sentence","mandatory requirement"],"theme":"law"},{"w":"mediation","pos":"noun","def":"A way of ending a disagreement by using a neutral person to help both sides agree.","defId":"Mediasi; cara menyelesaikan perselisihan dengan bantuan pihak netral agar kedua belah pihak sepakat.","ex":"The couple resolved their differences through mediation rather than a court battle.","exId":"Pasangan itu menyelesaikan perbedaan mereka melalui mediasi alih-alih berperkara di pengadilan.","colloc":["family mediation","through mediation","offer mediation"],"theme":"law"},{"w":"negligence","pos":"noun","def":"Failure to take the care a reasonable person would, resulting in harm to others.","defId":"Kelalaian; kegagalan bersikap hati-hati sebagaimana mestinya sehingga menimbulkan kerugian.","ex":"The hospital was sued for negligence after the patient's condition worsened.","exId":"Rumah sakit itu digugat atas kelalaian setelah kondisi pasien memburuk.","colloc":["gross negligence","medical negligence","sue for negligence"],"theme":"law"},{"w":"non-binding","pos":"adjective","def":"not legally forcing anyone to do what has been agreed","defId":"tidak mengikat secara hukum","ex":"The referendum was non-binding, so parliament was not obliged to act on the result.","exId":"Referendum itu tidak mengikat, sehingga parlemen tidak wajib menindaklanjuti hasilnya.","colloc":["non-binding agreement","non-binding resolution"],"theme":"law"},{"w":"notarise","pos":"verb","def":"to have a document made official by a notary","defId":"mengesahkan dokumen di hadapan notaris","ex":"You must notarise the affidavit before it can be submitted to the court.","exId":"Anda harus mengesahkan surat pernyataan itu di hadapan notaris sebelum dapat diajukan ke pengadilan.","colloc":["notarise a document","a notarised copy"],"theme":"law"},{"w":"null","pos":"adjective","def":"having no legal force; invalid, especially in the phrase 'null and void'","defId":"batal; tidak berlaku, terutama dalam ungkapan 'null and void'","ex":"The marriage was declared null after evidence of fraud emerged.","exId":"Pernikahan itu dinyatakan batal setelah muncul bukti penipuan.","colloc":["null and void","render null"],"theme":"law"},{"w":"oath","pos":"noun","def":"A solemn promise, especially to tell the truth in a court of law.","defId":"Sumpah; janji khidmat, terutama untuk berkata jujur di pengadilan.","ex":"The witness took an oath before giving evidence.","exId":"Saksi mengucapkan sumpah sebelum memberikan kesaksian.","colloc":["take an oath","under oath","swear an oath"],"theme":"law"},{"w":"obligatory","pos":"adjective","def":"required by a rule, law, or custom; that you must do","defId":"wajib; bersifat keharusan yang tidak bisa dihindari","ex":"Disclosing any conflict of interest is obligatory under the new code of conduct.","exId":"Mengungkapkan setiap konflik kepentingan bersifat wajib menurut kode etik yang baru.","colloc":["legally obligatory","obligatory disclosure"],"theme":"law"},{"w":"ombudsman","pos":"noun","def":"An official appointed to investigate people's complaints against public bodies or companies.","defId":"Ombudsman; pejabat yang ditunjuk untuk menyelidiki keluhan masyarakat terhadap lembaga publik atau perusahaan.","ex":"If the bank rejects your complaint, you can refer it to the financial ombudsman.","exId":"Jika bank menolak keluhan Anda, Anda dapat merujuknya ke ombudsman keuangan.","colloc":["financial ombudsman","refer to the ombudsman","ombudsman service"],"theme":"law"},{"w":"overturn","pos":"verb","def":"To officially change a legal decision so that it no longer has effect.","defId":"Membatalkan; secara resmi membalikkan suatu keputusan hukum.","ex":"The appeal court overturned the original conviction.","exId":"Pengadilan banding membatalkan vonis semula.","colloc":["overturn a verdict","overturn a conviction","overturn a ruling"],"theme":"law"},{"w":"perjury","pos":"noun","def":"The criminal offence of deliberately lying after taking an oath in court.","defId":"Sumpah palsu; tindak pidana sengaja berbohong setelah bersumpah di pengadilan.","ex":"He was charged with perjury after lying to the court under oath.","exId":"Dia didakwa melakukan sumpah palsu setelah berbohong kepada pengadilan di bawah sumpah.","colloc":["commit perjury","charged with perjury","perjury conviction"],"theme":"law"},{"w":"permissible","pos":"adjective","def":"allowed by the rules or by the law","defId":"diperbolehkan; diizinkan menurut aturan atau hukum","ex":"The court ruled that such evidence was not permissible at trial.","exId":"Pengadilan memutuskan bahwa bukti semacam itu tidak diperbolehkan dalam persidangan.","colloc":["legally permissible","permissible limit"],"theme":"law"},{"w":"plaintiff","pos":"noun","def":"The person who brings a legal case against someone else in court.","defId":"Pihak yang mengajukan gugatan terhadap orang lain di pengadilan; penggugat.","ex":"The plaintiff is seeking compensation for the damage to her property.","exId":"Penggugat menuntut ganti rugi atas kerusakan pada propertinya.","colloc":["the plaintiff claims","represent the plaintiff","plaintiff's lawyer"],"theme":"law"},{"w":"plea","pos":"noun","def":"A defendant's formal statement of guilt or innocence in court.","defId":"Pernyataan resmi terdakwa tentang bersalah atau tidaknya di pengadilan; pembelaan.","ex":"The defendant entered a plea of not guilty.","exId":"Terdakwa menyatakan pembelaan tidak bersalah.","colloc":["enter a plea","guilty plea","plea of not guilty"],"theme":"law"},{"w":"precedent","pos":"noun","def":"An earlier court decision that serves as an example or rule for later cases.","defId":"Preseden; keputusan pengadilan sebelumnya yang dijadikan pedoman untuk kasus berikutnya.","ex":"The judgment set a legal precedent that lower courts must follow.","exId":"Vonis itu menetapkan preseden hukum yang harus diikuti oleh pengadilan yang lebih rendah.","colloc":["set a precedent","legal precedent","follow precedent"],"theme":"law"},{"w":"prohibit","pos":"verb","def":"To officially forbid something, especially by law.","defId":"Melarang secara resmi, terutama melalui hukum.","ex":"The new law prohibits smoking in all public buildings.","exId":"Undang-undang baru itu melarang merokok di semua gedung publik.","colloc":["strictly prohibit","prohibit by law","expressly prohibit"],"theme":"law"},{"w":"provision","pos":"noun","def":"A condition or requirement included in a law or legal agreement.","defId":"Ketentuan atau persyaratan yang tercantum dalam hukum atau perjanjian.","ex":"The treaty includes a provision for the protection of minority languages.","exId":"Perjanjian itu memuat ketentuan untuk perlindungan bahasa minoritas.","colloc":["legal provision","statutory provision","under the provisions of"],"theme":"law"},{"w":"quash","pos":"verb","def":"to officially reject or cancel a decision or conviction","defId":"membatalkan putusan atau vonis secara resmi","ex":"The appeal court quashed his conviction after new evidence came to light.","exId":"Pengadilan banding membatalkan vonisnya setelah muncul bukti baru.","colloc":["quash a conviction","quash a verdict"],"theme":"law"},{"w":"redress","pos":"noun","def":"Compensation or a remedy for something wrong or unfair that has happened.","defId":"Ganti rugi atau pemulihan atas suatu kesalahan atau ketidakadilan.","ex":"Consumers can seek redress through the courts if a product is faulty.","exId":"Konsumen dapat menuntut ganti rugi melalui pengadilan jika suatu produk cacat.","colloc":["seek redress","legal redress","redress a grievance"],"theme":"law"},{"w":"regulation","pos":"noun","def":"An official rule made by a government or authority to control an activity.","defId":"Peraturan resmi yang dibuat oleh pemerintah atau otoritas untuk mengatur suatu kegiatan.","ex":"New safety regulations require all workers to wear protective equipment.","exId":"Peraturan keselamatan yang baru mewajibkan semua pekerja mengenakan alat pelindung.","colloc":["safety regulation","comply with regulations","government regulation"],"theme":"law"},{"w":"reprieve","pos":"noun","def":"an official order stopping or delaying a punishment, especially an execution","defId":"penangguhan hukuman; pengampunan sementara","ex":"The prisoner was granted a last-minute reprieve by the governor.","exId":"Narapidana itu diberi penangguhan hukuman pada saat-saat terakhir oleh gubernur.","colloc":["grant a reprieve","a last-minute reprieve"],"theme":"law"},{"w":"rescind","pos":"verb","def":"to officially cancel a law, decision, or agreement","defId":"mencabut atau membatalkan hukum, keputusan, atau perjanjian secara resmi","ex":"The board voted to rescind the controversial policy.","exId":"Dewan memberikan suara untuk mencabut kebijakan yang kontroversial itu.","colloc":["rescind a decision","rescind a contract"],"theme":"law"},{"w":"revoke","pos":"verb","def":"to officially cancel a right, permission, or licence","defId":"mencabut hak, izin, atau lisensi secara resmi","ex":"The court can revoke a driving licence after repeated offences.","exId":"Pengadilan dapat mencabut surat izin mengemudi setelah pelanggaran yang berulang.","colloc":["revoke a licence","revoke permission"],"theme":"law"},{"w":"ruling","pos":"noun","def":"An official decision made by a judge or court.","defId":"Putusan; keputusan resmi yang dibuat oleh hakim atau pengadilan.","ex":"The court's ruling set an important precedent for similar cases.","exId":"Putusan pengadilan itu menjadi preseden penting bagi kasus-kasus serupa.","colloc":["court ruling","landmark ruling","overturn a ruling"],"theme":"law"},{"w":"settlement","pos":"noun","def":"A formal agreement that ends a legal dispute, often involving payment.","defId":"Penyelesaian; kesepakatan resmi yang mengakhiri sengketa hukum, sering kali disertai pembayaran.","ex":"The two companies reached an out-of-court settlement.","exId":"Kedua perusahaan mencapai penyelesaian di luar pengadilan.","colloc":["reach a settlement","out-of-court settlement","settlement agreement"],"theme":"law"},{"w":"solicitor","pos":"noun","def":"A lawyer who gives legal advice and prepares documents, mainly outside court in the UK.","defId":"Pengacara yang memberi nasihat hukum dan menyiapkan dokumen, umumnya di luar persidangan di Inggris.","ex":"You should consult a solicitor before signing the tenancy agreement.","exId":"Anda sebaiknya berkonsultasi dengan solicitor sebelum menandatangani perjanjian sewa.","colloc":["consult a solicitor","family solicitor","solicitor's firm"],"theme":"law"},{"w":"statutory","pos":"adjective","def":"Required, permitted, or defined by a written law.","defId":"Sesuai undang-undang; diwajibkan atau ditetapkan oleh hukum tertulis.","ex":"Employers must meet their statutory obligations regarding sick pay.","exId":"Pemberi kerja harus memenuhi kewajiban menurut undang-undang terkait upah sakit.","colloc":["statutory obligation","statutory rights","statutory duty"],"theme":"law"},{"w":"subpoena","pos":"noun","def":"A legal document ordering a person to attend court or produce evidence.","defId":"Perintah hukum yang mewajibkan seseorang hadir di pengadilan atau menyerahkan bukti; panggilan pengadilan.","ex":"The witness was served with a subpoena to testify at the trial.","exId":"Saksi itu menerima panggilan pengadilan untuk memberikan kesaksian di persidangan.","colloc":["issue a subpoena","serve a subpoena","subpoena a witness"],"theme":"law"},{"w":"sue","pos":"verb","def":"To make a legal claim against someone, usually to obtain money.","defId":"Menggugat; mengajukan tuntutan hukum terhadap seseorang, biasanya untuk memperoleh ganti rugi.","ex":"She decided to sue the company for wrongful dismissal.","exId":"Dia memutuskan untuk menggugat perusahaan itu atas pemecatan yang tidak sah.","colloc":["sue for damages","threaten to sue","sue someone"],"theme":"law"},{"w":"sworn","pos":"adjective","def":"Made or given after promising under oath to tell the truth.","defId":"Yang diberikan di bawah sumpah; bersumpah.","ex":"She gave a sworn statement to the police describing the incident.","exId":"Dia memberikan pernyataan bersumpah kepada polisi yang menjelaskan kejadian itu.","colloc":["sworn statement","sworn testimony","sworn evidence"],"theme":"law"},{"w":"tribunal","pos":"noun","def":"A special court or panel appointed to settle a particular type of dispute.","defId":"Pengadilan atau majelis khusus yang dibentuk untuk menyelesaikan jenis sengketa tertentu.","ex":"The employee took her case to an employment tribunal after being unfairly dismissed.","exId":"Karyawan itu membawa kasusnya ke pengadilan ketenagakerjaan setelah dipecat secara tidak adil.","colloc":["employment tribunal","appear before a tribunal","tribunal hearing"],"theme":"law"},{"w":"unlawful","pos":"adjective","def":"Not permitted by law; illegal.","defId":"Melanggar hukum; tidak sah.","ex":"The court ruled that the dismissal was unlawful.","exId":"Pengadilan memutuskan bahwa pemecatan itu melanggar hukum.","colloc":["unlawful killing","unlawful detention","deemed unlawful"],"theme":"law"},{"w":"uphold","pos":"verb","def":"To confirm or support a legal decision that has been questioned.","defId":"Menguatkan; menegakkan atau mempertahankan suatu keputusan hukum.","ex":"The higher court is likely to uphold the original ruling.","exId":"Pengadilan yang lebih tinggi kemungkinan akan menguatkan putusan semula.","colloc":["uphold a ruling","uphold the law","uphold a decision"],"theme":"law"},{"w":"violate","pos":"verb","def":"to break or act against a law, agreement, or right","defId":"melanggar hukum, perjanjian, atau hak","ex":"Companies that violate data-protection regulations can be heavily fined.","exId":"Perusahaan yang melanggar peraturan perlindungan data dapat didenda berat.","colloc":["violate a law","violate human rights"],"theme":"law"},{"w":"void","pos":"adjective","def":"having no legal force or effect; not valid","defId":"batal; tidak berkekuatan hukum","ex":"Because one party was a minor, the judge declared the contract void.","exId":"Karena salah satu pihak masih di bawah umur, hakim menyatakan kontrak itu batal.","colloc":["null and void","declare void"],"theme":"law"},{"w":"voluntary","pos":"adjective","def":"done because you choose to, not because you are forced to","defId":"sukarela; atas kemauan sendiri tanpa paksaan","ex":"The witness gave a voluntary statement without being pressured by the police.","exId":"Saksi memberikan pernyataan secara sukarela tanpa ditekan oleh polisi.","colloc":["voluntary agreement","voluntary disclosure"],"theme":"law"},{"w":"waive","pos":"verb","def":"to choose not to use or insist on a right or claim","defId":"melepaskan atau tidak menuntut suatu hak; mengesampingkan","ex":"The defendant agreed to waive his right to remain silent.","exId":"Terdakwa setuju untuk melepaskan haknya untuk tetap diam.","colloc":["waive a right","waive a fee"],"theme":"law"},{"w":"waiver","pos":"noun","def":"An official statement that gives up a legal right or claim.","defId":"Pelepasan hak; pernyataan resmi yang melepaskan suatu hak atau tuntutan hukum.","ex":"Participants had to sign a waiver before taking part in the race.","exId":"Peserta harus menandatangani surat pelepasan hak sebelum mengikuti lomba.","colloc":["sign a waiver","liability waiver","waiver of rights"],"theme":"law"},{"w":"witness","pos":"verb","def":"to see an event and be able to describe it, or to sign a document to confirm it is genuine","defId":"menyaksikan suatu peristiwa; menandatangani dokumen sebagai saksi pengesah","ex":"The lawyer asked a colleague to witness the signing of the will.","exId":"Pengacara meminta seorang rekan untuk menyaksikan penandatanganan surat wasiat itu.","colloc":["witness a signature","witness the signing"],"theme":"law"}];
